class Token:
    def __init__(self, value):
        self.value = value
    def __repr__(self):
        return f"Token({self.value})"
    def __str__(self):
        return f"Value {self.value}"
print(repr(Token(2)))

class Counter:
    def __init__(self, value):
        ___.value = value
print(Counter(2).value)

